use crate::fea::StressGrid;
use crate::field::GoverningScalar;
use crate::geom::{self, LayerSurface, Vec3};
pub fn extract_iso_surfaces(field:&GoverningScalar,grid:&StressGrid,layer_height:f64,thickness:f64)->Vec<LayerSurface>{if field.is_empty()||grid.is_empty(){return Vec::new()}let(min_v,max_v)=field.range();let span=(max_v-min_v).abs();if span<1e-12{return vec![single_mid_layer(field,thickness)]}let z_extent=(grid.dims[2].saturating_sub(1)as f64)*grid.spacing[2];let n_layers=if layer_height>1e-9{((z_extent/layer_height).round()as usize).clamp(1,64)}else{1};let mut layers=Vec::with_capacity(n_layers);for li in 0..n_layers{let level=min_v+(li as f64+0.5)/n_layers as f64*span;let(points,normals)=sample_level_set(field,level);if points.len()>=3{layers.push(LayerSurface{id:li as u32,points,normals,thickness,sequence:li as u32});}}layers}
fn single_mid_layer(field:&GoverningScalar,thickness:f64)->LayerSurface{let k=field.dims[2]/2;let mut points=Vec::new();let mut normals=Vec::new();for j in 0..field.dims[1]{for i in 0..field.dims[0]{let idx=field.index(i,j,k);points.push(field.position(i,j,k));normals.push(field.gradients[idx]);}}LayerSurface{id:0,points,normals,thickness,sequence:0}}
fn sample_level_set(field:&GoverningScalar,level:f64)->(Vec<Vec3>,Vec<Vec3>){let mut points=Vec::new();let mut normals=Vec::new();let nx=field.dims[0];let ny=field.dims[1];let nz=field.dims[2];let edge=|i0:usize,j0:usize,k0:usize,i1:usize,j1:usize,k1:usize,points:&mut Vec<Vec3>,normals:&mut Vec<Vec3>|{let a=field.index(i0,j0,k0);let b=field.index(i1,j1,k1);let va=field.values[a];let vb=field.values[b];if(va-level)*(vb-level)>0.0{return}let t=if(vb-va).abs()<1e-14{0.5}else{((level-va)/(vb-va)).clamp(0.0,1.0)};points.push(geom::lerp(field.position(i0,j0,k0),field.position(i1,j1,k1),t));normals.push(geom::normalize(geom::lerp(field.gradients[a],field.gradients[b],t)));};for k in 0..nz{for j in 0..ny{for i in 0..nx{if i+1<nx{edge(i,j,k,i+1,j,k,&mut points,&mut normals)}if j+1<ny{edge(i,j,k,i,j+1,k,&mut points,&mut normals)}if k+1<nz{edge(i,j,k,i,j,k+1,&mut points,&mut normals)}}}}(points,normals)}
